<script setup lang="ts">
import { ref, watch } from 'vue'
import { History } from 'lucide-vue-next'
import Pager from './Pager.vue'
import { api, dateTimeLabel, messageOf, query } from '../api'
import type { Page } from '../types'
interface HistoryEntry {id:string|number;operator:string;created_at:string;action:string;before?:unknown;after?:unknown;before_json?:string;after_json?:string}
const props=defineProps<{kind:string;id:string;revision?:number}>();const entries=ref<HistoryEntry[]>([]),total=ref(0),offset=ref(0),loading=ref(false),error=ref(''),expanded=ref(false),loaded=ref(false);const limit=10
const labels:Record<string,string>={acceptance_criteria:'验收准则',acceptance_note:'验收说明',change_note:'修订原因',revision:'需求修订',task_ids:'关联任务',linked_tasks:'关联任务快照',code:'编号',name:'名称',title:'标题',content:'内容',description:'说明',customer:'客户',phase:'阶段',manager:'项目负责人',start_date:'开始日期',end_date:'结束日期',status:'状态',progress:'完成进度',assignee:'负责人',owner:'负责人',plan_start:'计划开始',plan_end:'计划结束',actual_start:'实际开始',actual_end:'实际结束',estimate_hours:'预计工时',actual_hours:'已记工时',priority:'优先级',parent_id:'上级任务',project_id:'所属项目',wbs_code:'WBS 编码',sort_order:'排序',type:'记录类型',location:'地点',occurred_at:'记录发生时间',tags:'标签',attachments:'图片附件',root_cause:'根因分析',solution:'解决方案',verify_result:'验证结果',rejection_reason:'驳回原因',due_at:'截止时间',source:'来源',severity:'严重程度',closed_at:'关闭时间',deleted_at:'移入回收站时间',reopen_reason:'重开原因',reason:'原因',period_type:'周期',log_date:'日志日期',meeting_date:'会议日期',attendees:'参会人',minutes:'工时分钟数',note:'说明',work_date:'工作日期',reminder_due_at:'提醒时间',person_name:'人员姓名',next_plan:'后续计划',blockers:'阻碍与协调',source_snapshot:'汇总来源'}
const actions:Record<string,string>={create:'创建',update:'更新',delete:'移入回收站',soft_delete:'移入回收站',restore:'从回收站恢复',move:'移动任务',reopen:'重开任务',transition:'流转状态',complete:'完成提醒',done:'完成提醒',batch:'批量修改',batch_update:'批量修改',rollup:'重算任务汇总',reminder_change:'更新关联提醒'}
function object(value:unknown):Record<string,unknown>{if(typeof value==='string'){try{return JSON.parse(value)||{}}catch{return{content:value}}}return value&&typeof value==='object'?value as Record<string,unknown>:{}}
function changes(entry:HistoryEntry){const before=object(entry.before??entry.before_json),after=object(entry.after??entry.after_json);return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(key=>!['id','created_at','updated_at','version','sha256','has_children','overdue','depth','order','actual_minutes','actual_hours'].includes(key)&&JSON.stringify(before[key])!==JSON.stringify(after[key])).map(key=>({key,label:labels[key]||key,before:before[key],after:after[key]}))}
function display(value:unknown,key:string){if(value===null||value===undefined||value==='')return '（空）';if(key==='attachments'&&Array.isArray(value))return value.length+' 个附件';if(Array.isArray(value))return value.join('、');if(key==='source_snapshot'&&value&&typeof value==='object'){const s=value as Record<string,unknown>;return `${Array.isArray(s.team_entries)?s.team_entries.length:0} 份人员记录、${Array.isArray(s.time_entries)?s.time_entries.length:0} 条工时、${Array.isArray(s.tasks)?s.tasks.length:0} 项任务`}if(typeof value==='object')return JSON.stringify(value);if(['occurred_at','due_at','closed_at','deleted_at','reminder_due_at'].includes(key)&&String(value).includes('T'))return dateTimeLabel(String(value));return String(value)}
async function load(){if(!props.id)return;loading.value=true;error.value='';try{const page=await api<Page<HistoryEntry>>(`/api/${props.kind}/${props.id}/history?${query({limit,offset:offset.value})}`);entries.value=page.items;total.value=page.total;loaded.value=true}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
function toggle(event:Event){expanded.value=(event.target as HTMLDetailsElement).open;if(expanded.value&&!loaded.value)void load()}
watch(()=>[props.id,props.kind,props.revision],()=>{loaded.value=false;offset.value=0;if(expanded.value)void load()})
function page(next:number){offset.value=next;void load()}
</script>
<template><details class="entity-history" @toggle="toggle"><summary><History :size="16"/>操作历史<span v-if="loaded">{{total}} 条</span></summary><p v-if="loading" class="loading-message">正在读取操作历史…</p><div v-else-if="error" class="form-error" role="alert">{{error}} <button type="button" class="text-button" @click="load">重试</button></div><p v-else-if="loaded&&!entries.length" class="history-empty">暂无操作历史</p><ol v-else class="history-events"><li v-for="entry in entries" :key="entry.id"><div class="history-event-meta"><strong>{{entry.operator||'本人'}}</strong><span>{{actions[entry.action]||entry.action}}</span><time>{{dateTimeLabel(entry.created_at)}}</time></div><dl v-if="changes(entry).length"><template v-for="change in changes(entry)" :key="change.key"><dt>{{change.label}}</dt><dd><del>{{display(change.before,change.key)}}</del><span aria-hidden="true"> → </span><ins>{{display(change.after,change.key)}}</ins></dd></template></dl><p v-else class="input-hint">操作已记录，未涉及可展示的字段变更。</p></li></ol><Pager v-if="loaded" :offset="offset" :limit="limit" :total="total" @change="page"/></details></template>
